package com.oms.order.service;

import com.oms.messaging.*;
import com.oms.common.api.OrderStockClient;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;
import org.springframework.context.support.PropertySourcesPlaceholderConfigurer;
import org.springframework.test.util.ReflectionTestUtils;
import javax.sql.DataSource;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderIntakeMessageTest {
 static final String C="MQ_VERIFY";static AnnotationConfigApplicationContext context;static OrderRepository repo;static MessageOutbox out;static JdbcTemplate db;
 OrderPullMessage pull;OrderConvertMessage convert;ConfiguredPushReader source;OrderCatalog catalog;
 @Configuration @EnableTransactionManagement static class Config {
  @Bean static PropertySourcesPlaceholderConfigurer properties(){PropertySourcesPlaceholderConfigurer p=new PropertySourcesPlaceholderConfigurer();Properties values=new Properties();values.setProperty("oms.messaging.service","order");p.setProperties(values);return p;}
  @Bean DataSource dataSource(){String url=System.getenv("ORDER_TEST_URL");if(url==null||!url.contains("/order_workspace_test?"))throw new IllegalStateException("Disposable schema required");return new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD"));}
  @Bean JdbcTemplate jdbcTemplate(DataSource ds){return new JdbcTemplate(ds);}
  @Bean PlatformTransactionManager transactionManager(DataSource ds){return new DataSourceTransactionManager(ds);}
  @Bean OrderRepository repository(){return new OrderRepository();}
  @Bean MessageOutbox outbox(){return new MessageOutbox();}
 }
 @BeforeAll static void start(){Assumptions.assumeTrue(System.getenv("ORDER_TEST_URL")!=null);context=new AnnotationConfigApplicationContext(Config.class);repo=context.getBean(OrderRepository.class);out=context.getBean(MessageOutbox.class);db=repo.db();}
 @AfterAll static void stop(){if(context!=null)context.close();}
 @BeforeEach void setup(){for(String table:Arrays.asList("oms_message_attempt","oms_message_outbox","oms_order_review_event","oms_order_review_config","oms_order_process_log","oms_order_line","oms_order","oms_platform_order_line","oms_platform_order","oms_order_pull_item","oms_order_pull_task","oms_order_pull_config"))db.update("DELETE FROM "+table+" WHERE company_code=?",C);db.update("INSERT INTO oms_order_pull_config(company_code,channel_id,channel_name,source_key,seller_nick,owner_code,store_codes,initial_time,cursor_time,auto_convert,allowed_trade_types) VALUES (?,1,'queue test','mq-fixture','seller','OWNER','[\"W1\"]','2026-10-01 00:00:00','2026-10-01 00:00:00',1,'[\"fixed\"]')",C);db.update("UPDATE oms_order_pull_config SET enabled=0 WHERE company_code=?",C);catalog=mock(OrderCatalog.class);source=mock(ConfiguredPushReader.class);pull=new OrderPullMessage();pull.repository=repo;pull.catalog=catalog;pull.push=source;convert=new OrderConvertMessage();convert.repository=repo;convert.processor=mock(OrderProcessor.class);}
 long task(String kind){return repo.newTask(C,1,kind,"2026-10-01 00:00:00","2026-10-02 00:00:00","tester");}
 Map<String,Object> notification(String kind,long id){return db.queryForMap("SELECT * FROM oms_message_outbox WHERE company_code=? AND message_type=? AND business_id=? ORDER BY id DESC LIMIT 1",C,kind,String.valueOf(id));}
 MessageRuntime runtime(MessageHandler handler){MessageRuntime r=new MessageRuntime();ReflectionTestUtils.setField(r,"outbox",out);ReflectionTestUtils.setField(r,"handlers",Collections.singletonList(handler));ReflectionTestUtils.setField(r,"tenants",mock(com.oms.common.tenant.TenantRouting.class));return r;}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE company_code=?",Long.class,C);}
 Map<String,Object> row(int i){try{String tid=new java.math.BigInteger("984000000000000000").add(java.math.BigInteger.valueOf(i)).toString();com.fasterxml.jackson.databind.JsonNode payload=JSON.readTree(TmallOrderParserTest.payload("25"));com.fasterxml.jackson.databind.node.ObjectNode trade=(com.fasterxml.jackson.databind.node.ObjectNode)payload.path("trade_fullinfo_get_response").path("trade");trade.put("tid",tid);((com.fasterxml.jackson.databind.node.ObjectNode)trade.path("orders").path("order").get(0)).put("oid",tid+"1");Map<String,Object> row=new LinkedHashMap<>();row.put("tid",tid);row.put("status","WAIT_SELLER_SEND_GOODS");row.put("type","fixed");row.put("seller_nick","seller");row.put("created","2026-10-01 00:00:00");row.put("modified","2026-10-01 01:00:00");row.put("jdp_modified","2026-10-01 01:00:00");row.put("jdp_response",payload.toString());return row;}catch(Exception e){throw new RuntimeException(e);}}
 long platform(){String lease="platform-fixture";assertTrue(repo.claim(C,1,lease));long task=task("MANUAL");try{repo.page(C,1,lease,repo.nextTask(C,1,lease),Collections.singletonList(row(1)),50);}finally{repo.release(C,1,lease);}return db.queryForObject("SELECT id FROM oms_platform_order WHERE company_code=?",Long.class,C);}
 @Test void taskAndWakeupRollbackTogether(){assertThrows(RuntimeException.class,()->out.tx(()->{task("MANUAL");throw new RuntimeException("rollback");}));assertEquals(0,count("oms_order_pull_task"));assertEquals(0,count("oms_message_outbox"));}
 @Test void committedPageResumesAfterLostAckAndDuplicateCannotRepeatRead(){long id=task("MANUAL");List<Map<String,Object>> first=new ArrayList<>();for(int i=1;i<=50;i++)first.add(row(i));when(source.read(eq(C),eq("mq-fixture"),eq("seller"),anyMap(),eq(50))).thenReturn(first,Collections.singletonList(row(51)));MessageRuntime r=runtime(pull);Map<String,Object> message=notification("ORDER_PULL",id);assertTrue(r.execute(C,message,"MQ"));assertEquals(50,count("oms_platform_order"));assertFalse(r.execute(C,message,"MQ"));db.update("UPDATE oms_message_outbox SET next_process_at=NOW() WHERE event_id=?",message.get("event_id"));assertTrue(r.execute(C,out.row(C,text(message,"event_id")),"COMPENSATION"));assertEquals(51,count("oms_platform_order"));assertEquals(51,db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox WHERE company_code=? AND message_type='ORDER_CONVERT'",Long.class,C));assertFalse(r.execute(C,message,"MQ"));verify(source,times(2)).read(anyString(),anyString(),anyString(),anyMap(),anyInt());assertEquals("SUCCESS",db.queryForObject("SELECT status FROM oms_order_pull_task WHERE id=?",String.class,id));}
 @Test void failedAutomaticPageDoesNotAdvanceCursorOrLeaveConversionWakeups(){long id=task("AUTO");Map<String,Object> bad=row(1);bad.put("seller_nick","different-seller");when(source.read(anyString(),anyString(),anyString(),anyMap(),anyInt())).thenReturn(Arrays.asList(row(2),bad));MessageHandler.Outcome result=pull.handle(C,notification("ORDER_PULL",id));assertEquals("WAITING",result.state);assertEquals(0,count("oms_platform_order"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox WHERE company_code=? AND message_type='ORDER_CONVERT'",Integer.class,C));assertEquals("2026-10-01 00:00:00",text(pull.task(C,id),"page_time"));}
 @Test void sameShopPullAndConversionWaitWithoutResettingFailures(){long id=platform();long task=task("MANUAL");assertTrue(repo.claim(C,1,"other-worker"));try{assertTrue(pull.handle(C,notification("ORDER_PULL",task)).preserveAttempts);assertTrue(convert.handle(C,notification("ORDER_CONVERT",id)).preserveAttempts);verifyNoInteractions(convert.processor,source);}finally{repo.release(C,1,"other-worker");}}
 @Test void newSourceVersionEndsOldNotificationBeforeBusinessEntry(){long id=platform();Map<String,Object> old=notification("ORDER_CONVERT",id);repo.conversionChanged(C,id,true);assertEquals("SUCCESS",convert.handle(C,old).state);verifyNoInteractions(convert.processor);assertNotEquals(old.get("event_id"),notification("ORDER_CONVERT",id).get("event_id"));}
 @Test void conversionUsesOriginalStockRulesAndCompletedDuplicateDoesNotCallStockAgain(){long id=platform();OrderStockClient stock=mock(OrderStockClient.class);Map<String,Object> receipt=new HashMap<>();receipt.put("platform_oid",text(row(1),"tid")+"1");receipt.put("sku_sn","A");receipt.put("reserved_quantity",5);receipt.put("reason","");when(stock.execute(anyString(),anyString(),any(),anyString())).thenReturn(R.ok(Collections.singletonList(receipt)));when(catalog.goods(eq(C),anyList())).thenReturn(Collections.singletonMap("A",Collections.singletonList(Collections.emptyMap())));OrderProcessor processor=new OrderProcessor();ReflectionTestUtils.setField(processor,"repository",repo);ReflectionTestUtils.setField(processor,"catalog",catalog);ReflectionTestUtils.setField(processor,"inventory",stock);convert.processor=processor;MessageRuntime r=runtime(convert);Map<String,Object> m=notification("ORDER_CONVERT",id);assertTrue(r.execute(C,m,"MQ"));assertEquals("SUCCESS",out.row(C,text(m,"event_id")).get("process_state"));assertEquals(1,count("oms_order"));assertEquals("SUCCESS",convert.handle(C,m).state);verify(stock,times(1)).execute(eq("register"),anyString(),any(),anyString());verify(stock,times(1)).execute(eq("reserve"),anyString(),any(),anyString());}
 @Test void blockingUpdateCannotReachInventoryAndFailureCannotBeAutoRequeued(){long id=platform();Map<String,Object> m=notification("ORDER_CONVERT",id);db.update("UPDATE oms_platform_order SET change_pending=1 WHERE company_code=? AND id=?",C,id);assertEquals("FAILED",convert.handle(C,m).state);verifyNoInteractions(convert.processor);convert.failed(C,m,"blocked");repo.conversionChanged(C,id,false);assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox WHERE company_code=? AND message_type='ORDER_CONVERT'",Integer.class,C));}
 @Test void retryPreservesPageCursorAndInvalidatesEarlierTaskVersion(){long id=task("MANUAL");Map<String,Object> m=notification("ORDER_PULL",id);db.update("UPDATE oms_order_pull_task SET page_time='2026-10-01 01:00:00',page_tid='123',status='FAILED' WHERE company_code=? AND id=?",C,id);repo.retryPull(C,id,"tester");assertEquals("2026-10-01 01:00:00",text(pull.task(C,id),"page_time"));assertEquals("123",text(pull.task(C,id),"page_tid"));assertEquals("SUCCESS",pull.handle(C,m).state);verifyNoInteractions(source);assertEquals(2,db.queryForObject("SELECT work_version FROM oms_order_pull_task WHERE id=?",Integer.class,id));}
 @Test void pageProgressAndPullTaskDetailsAreCompanyScoped(){long id=task("MANUAL");List<Map<String,Object>> records=new ArrayList<>();records.add(new HashMap<>(Collections.singletonMap("id",id)));repo.messageProgress("OTHER",records,"ORDER_PULL");assertNull(records.get(0).get("message"));assertThrows(IllegalArgumentException.class,()->pull.task("OTHER",id));}
 @Test void scannerOnlyPublishesIntakeWorkAndNeverReadsThePushSource(){platform();task("MANUAL");OrderProcessor p=new OrderProcessor();ReflectionTestUtils.setField(p,"repository",repo);ReflectionTestUtils.setField(p,"voids",mock(OrderVoidService.class));ReflectionTestUtils.setField(p,"push",source);ReflectionTestUtils.setField(p,"catalog",catalog);p.shop(C,1);long before=count("oms_message_outbox");p.shop(C,1);assertEquals(before,count("oms_message_outbox"));verifyNoInteractions(source,catalog);}
 @Test void exhaustedPullIsVisibleOnBusinessTaskAndManualRetryResumesOriginalRange(){long id=task("MANUAL");Map<String,Object> original=notification("ORDER_PULL",id);db.update("UPDATE oms_message_outbox SET business_attempts=7 WHERE event_id=?",original.get("event_id"));when(source.read(anyString(),anyString(),anyString(),anyMap(),anyInt())).thenThrow(new RuntimeException(new java.net.SocketTimeoutException("simulated")));MessageRuntime r=runtime(pull);r.execute(C,notification("ORDER_PULL",id),"MQ");assertEquals("FAILED",text(pull.task(C,id),"status"));assertEquals("FAILED",out.row(C,text(original,"event_id")).get("process_state"));r.retry(C,text(original,"event_id"),"tester","source recovered");Map<String,Object> latest=notification("ORDER_PULL",id);assertEquals(original.get("event_id"),latest.get("parent_event_id"));doReturn(Collections.emptyList()).when(source).read(anyString(),anyString(),anyString(),anyMap(),anyInt());r.execute(C,latest,"MQ");assertEquals("SUCCESS",text(pull.task(C,id),"status"));}

 @Test void disabledCompanyCannotStartNewIntakeOrConsumeRetryBudget(){long id=task("MANUAL");MessageRuntime r=runtime(pull);com.oms.common.tenant.TenantRouting tenants=mock(com.oms.common.tenant.TenantRouting.class);when(tenants.open(C)).thenThrow(new IllegalArgumentException("company disabled for new intake"));ReflectionTestUtils.setField(r,"tenants",tenants);Map<String,Object> m=notification("ORDER_PULL",id);assertThrows(IllegalArgumentException.class,()->r.execute(C,m,"MQ"));assertEquals("PENDING",out.row(C,text(m,"event_id")).get("process_state"));verifyNoInteractions(source,catalog);}

}
